package retry

import (
	"context"
	"math"
	"time"
)

type Policy struct {
	MaxAttempts int
	BaseDelay   time.Duration
	MaxDelay    time.Duration
	Multiplier  float64
}

func Do(ctx context.Context, p Policy, fn func() error) error {
	var err error
	for i := 0; i < p.MaxAttempts; i++ {
		if err = fn(); err == nil {
			return nil
		}
		d := time.Duration(float64(p.BaseDelay) * math.Pow(p.Multiplier, float64(i)))
		if d > p.MaxDelay {
			d = p.MaxDelay
		}
		t := time.NewTimer(d)
		select {
		case <-ctx.Done():
			t.Stop()
			return ctx.Err()
		case <-t.C:
		}
	}
	return err
}
