from dataclasses import dataclass, field
from typing import Iterator

GAP_SECONDS = 1800

@dataclass
class Event:
    user_id: str
    ts: float
    kind: str
    props: dict = field(default_factory=dict)

@dataclass
class Session:
    user_id: str
    start: float
    end: float
    events: list = field(default_factory=list)

def split_sessions(events: Iterator[Event]) -> list:
    sessions = []
    cur = None
    for e in events:
        if cur is None:
            cur = Session(e.user_id, e.ts, e.ts, [e])
            continue
        if e.user_id != cur.user_id:
            sessions.append(cur)
            cur = Session(e.user_id, e.ts, e.ts, [e])
            continue
        if e.ts - cur.end > GAP_SECONDS:
            sessions.append(cur)
            cur = Session(e.user_id, e.ts, e.ts, [e])
        else:
            cur.events.append(e)
            cur.end = e.ts
    if cur is not None:
        sessions.append(cur)
    return sessions

def session_stats(sessions: list) -> dict:
    out = {}
    for s in sessions:
        d = s.end - s.start
        out.setdefault(s.user_id, []).append({
            'start': s.start,
            'duration': d,
            'n_events': len(s.events),
