// internal/worker/pool.go
package worker

import (
    "context"
    "sync"
    "sync/atomic"
    "time"
)

type Job struct {
    ID      string
    Payload []byte
    Attempt int
    EnqueuedAt time.Time
}

type Result struct {
    JobID string
    Err   error
    Duration time.Duration
}

type Pool struct {
    workers   int
    queue     chan Job
    results   chan Result
    wg        sync.WaitGroup
    processed int64
    failed    int64
    handler   func(context.Context, Job) error
}

func NewPool(workers int, queueSize int, h func(context.Context, Job) error) *Pool {
    return &Pool{
        workers: workers,
        queue:   make(chan Job, queueSize),
        results: make(chan Result, queueSize),
        handler: h,
    }
}

func (p *Pool) Start(ctx context.Context) {
    for i := 0; i < p.workers; i++ {
        p.wg.Add(1)
        go func(id int) {
            defer p.wg.Done()
            for {
                select {
                case <-ctx.Done():
                    return
                case job := <-p.queue:
                    start := time.Now()
                    err := p.handler(ctx, job)
                    atomic.AddInt64(&p.processed, 1)
                    if err != nil {
                        atomic.AddInt64(&p.failed, 1)
                    }
                    p.results <- Result{JobID: job.ID, Err: err, Duration: time.Since(start)}
                }
            }
        }(i)
    }
}

func (p *Pool) Submit(j Job) {
    p.queue <- j
}

func (p *Pool) Drain() {
    close(p.queue)
    p.wg.Wait()
    close(p.results)
}

func (p *Pool) Stats() (int64, int64) {
    return atomic.LoadInt64(&p.processed), atomic.LoadInt64(&p.failed)
}
