// internal/worker/dispatch.go
package worker

import (
    "context"
    "encoding/json"
    "time"

    "github.com/redis/go-redis/v9"
)

const retryTopic = "jobs:retry"
const deadTopic  = "jobs:dead"

type Dispatcher struct {
    rdb   *redis.Client
    pool  *Pool
    maxAttempt int
}

func NewDispatcher(rdb *redis.Client, pool *Pool, maxAttempt int) *Dispatcher {
    return &Dispatcher{rdb: rdb, pool: pool, maxAttempt: maxAttempt}
}

// Run 从 redis list 阻塞读任务并提交给 worker pool
func (d *Dispatcher) Run(ctx context.Context) error {
    for {
        res, err := d.rdb.BLPop(ctx, 5*time.Second, "jobs:pending").Result()
        if err == redis.Nil {
            continue
        }
        if err != nil {
            return err
        }
        var j Job
        if err := json.Unmarshal([]byte(res[1]), &j); err != nil {
            d.rdb.RPush(ctx, deadTopic, res[1])
            continue
        }
        j.Attempt++
        d.pool.Submit(j)
    }
}

// RetryLoop 每分钟把到期的重试任务挪回 pending
func (d *Dispatcher) RetryLoop(ctx context.Context) {
    ticker := time.NewTicker(time.Minute)
    defer ticker.Stop()
    for {
        select {
        case <-ctx.Done():
            return
        case <-ticker.C:
            jobs, _ := d.rdb.LRange(ctx, retryTopic, 0, -1).Result()
            for _, raw := range jobs {
                var j Job
                if json.Unmarshal([]byte(raw), &j) == nil && j.Attempt < d.maxAttempt {
                    d.rdb.RPush(ctx, "jobs:pending", raw)
                } else {
                    d.rdb.RPush(ctx, deadTopic, raw)
                }
            }
            d.rdb.Del(ctx, retryTopic)
        }
    }
}
